auto func (auto value){  
    auto sum = 0;  
    auto product = 1;  
    for(auto& elem : value) {  
        if(elem % 2 == 0) sum += elem;  
        product *= elem;  
    }  
    return std::make_tuple(sum, product);  
}

auto func (auto value){  
    int count = 0;  
    for(auto i = value.begin(); i != value.end(); ++i) {  
        if(*i % 2 == 0) ++count;  
    }  
    return count;  
}

auto func (auto value){ 
    int count = 0;
    for(auto i = 0; i < value.size(); ++i){
        if(value[i] % 2 == 0) ++count;
    }
    return count;
}

